begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','private.correction_context','INSERT,SELECT,UPDATE,DELETE'),'Correction capability cannot be forged or read by clients');
select ok(not has_function_privilege('authenticated','private.reverse_event(uuid,text)','EXECUTE'),'Clients cannot call raw reversal primitive');
select ok(not has_function_privilege('authenticated','private.replace_recognition(uuid,uuid)','EXECUTE'),'Clients cannot rewrite earning recognition');
select ok(not has_function_privilege('authenticated','private.post_refund_funding(uuid,integer,jsonb)','EXECUTE'),'Refund financing requires public semantic authorization');
select ok(not has_table_privilege('carrier_finance','private.trip_recognition','INSERT,UPDATE,DELETE'),'Correction kernel cannot directly rewrite recognition');
select ok(not has_table_privilege('authenticated','public.financial_events','INSERT,UPDATE,DELETE') and not has_table_privilege('authenticated','public.expenses','UPDATE,DELETE'),'No direct financial correction or evidence deletion');
select ok(not has_table_privilege('carrier_finance','public.financial_events','UPDATE,DELETE') and not has_table_privilege('carrier_finance','public.journal_lines','UPDATE,DELETE'),'Financial history remains append-only for correction owner');
select ok(not pg_has_role('postgres','carrier_finance','SET') and not pg_has_role('postgres','carrier_security','SET') and not pg_has_role('postgres','carrier_earnings','SET'),'All temporary migration role access revoked');
select ok(not has_schema_privilege('carrier_finance','private','CREATE') and not has_schema_privilege('carrier_earnings','private','CREATE'),'No lingering schema creation grants');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where oid in('public.correct_financial_event(uuid,uuid,integer,jsonb)'::regprocedure,'public.cancel_and_adjust(uuid,uuid,integer,jsonb)'::regprocedure,'private.reverse_event(uuid,text)'::regprocedure)),'Correction definers pin search path');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.correct_financial_event(gen_random_uuid(),gen_random_uuid(),1,'{}')$$,'42501','FORBIDDEN','Correction requires live staff');
select throws_ok($$select public.cancel_and_adjust(gen_random_uuid(),gen_random_uuid(),1,'{}')$$,'42501','FORBIDDEN','Cancellation requires live staff');
select throws_ok($$select public.post_financial_event('RECOVERY_RECEIPT',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Recovery requires live staff');
select throws_ok($$select public.post_financial_event('REFUND_FUNDING',gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Personal refund financing requires live staff');
select throws_ok($$select public.list_financial_history()$$,'42501','FORBIDDEN','History requires live staff');
reset role;
select * from finish();
rollback;
